8	func TestValidate(t *testing.T) {
9		tests := []struct {
10			name    string
11			address string
12			wantErr error
13		}{
14			{"valid simple", "user@example.com", nil},
15			{"valid with dots", "first.last@example.com", nil},
16			{"valid with plus", "user+tag@example.com", nil},
17			{"valid with hyphen", "user-name@example.com", nil},
18			{"valid subdomain", "user@mail.example.com", nil},
19			{"empty string", "", ErrEmptyAddress},
20			{"whitespace only", "   ", ErrEmptyAddress},
21			{"no at sign", "userexample.com", ErrInvalidFormat},
22			{"no domain", "user@", ErrInvalidFormat},
23			{"no local", "@example.com", ErrInvalidFormat},
24			{"double at", "user@@example.com", ErrInvalidFormat},
25			{"spaces in address", "user @example.com", ErrInvalidFormat},
26			{"no TLD", "user@example", ErrInvalidFormat},
27			{"leading dot local", ".user@example.com", ErrInvalidLocal},
28			{"trailing dot local", "user.@example.com", ErrInvalidLocal},
29			{"double dot local", "user..name@example.com", ErrInvalidLocal},
30			{"leading dot domain", "user@.example.com", ErrInvalidDomain},
31			{"trailing dot domain", "user@example.com.", ErrInvalidDomain},
32			{"double dot domain", "user@example..com", ErrInvalidDomain},
33			{"leading hyphen domain", "user@-example.com", ErrInvalidDomain},
34			{"trailing hyphen domain", "user@example-.com", ErrInvalidDomain},
35		}
36	
37		for _, tt := range tests {
38			t.Run(tt.name, func(t *testing.T) {
39				err := Validate(tt.address)
40				if tt.wantErr == nil {
41					if err != nil {
42						t.Errorf("Validate(%q) = %v, want nil", tt.address, err)
43					}
44					return
45				}
46				if err == nil {
47					t.Errorf("Validate(%q) = nil, want error", tt.address)
48					return
49				}
50				var ve *ValidationError
51				if !errors.As(err, &ve) {
52					t.Errorf("error is not *ValidationError: %v", err)
53					return
54				}
55				if !errors.Is(ve.Err, tt.wantErr) {
56					t.Errorf("Validate(%q) inner error = %v, want %v", tt.address, ve.Err, tt.wantErr)
57				}
58			})
59		}
60	}
61	
62	func TestValidateBulk(t *testing.T) {
63		addresses := []string{
64			"user@example.com",
65			"invalid",
66			"good@test.org",
67			"@bad.com",
68		}
69	
70		errs := ValidateBulk(addresses)
71		if len(errs) != 2 {
72			t.Errorf("ValidateBulk returned %d errors, want 2", len(errs))
73		}
74		if _, ok := errs["invalid"]; !ok {
75			t.Error("expected error for 'invalid'")
76		}
77		if _, ok := errs["@bad.com"]; !ok {
78			t.Error("expected error for '@bad.com'")
79		}
80		if _, ok := errs["user@example.com"]; ok {
81			t.Error("unexpected error for 'user@example.com'")
82		}
83	}
84	
