87		expected := `invalid email "bad@": invalid email format`
88		if err.Error() != expected {
89			t.Errorf("Error() = %q, want %q", err.Error(), expected)
90		}
91		if !errors.Is(err.Unwrap(), ErrInvalidFormat) {
92			t.Error("Unwrap() should return ErrInvalidFormat")
93		}
94	}
95

