8	// Message represents an email message.
9	type Message struct {
10		From    string
11		To      []string
12		CC      []string
13		BCC     []string
14		Subject string
15		Body    string
16		HTML    bool
17	}
18	
19	// Validate checks that the message is ready to send.
20	func (m *Message) Validate() error {
21		if len(m.To) == 0 && len(m.CC) == 0 && len(m.BCC) == 0 {
22			return ErrNoRecipients
23		}
24		if strings.TrimSpace(m.Subject) == "" {
25			return ErrEmptySubject
26		}
27		if strings.TrimSpace(m.Body) == "" {
28			return ErrEmptyBody
29		}
30	
31		allRecipients := append(m.To, m.CC...)
32		allRecipients = append(allRecipients, m.BCC...)
33		for _, addr := range allRecipients {
34			if err := Validate(addr); err != nil {
35				return fmt.Errorf("recipient %q: %w", addr, err)
36			}
37		}
38		if m.From != "" {
39			if err := Validate(m.From); err != nil {
40				return fmt.Errorf("sender %q: %w", m.From, err)
41			}
42		}
43		return nil
44	}
45	
46	// AllRecipients returns a combined list of To, CC, and BCC addresses.
47	func (m *Message) AllRecipients() []string {
48		total := len(m.To) + len(m.CC) + len(m.BCC)
49		recipients := make([]string, 0, total)
50		recipients = append(recipients, m.To...)
51		recipients = append(recipients, m.CC...)
52		recipients = append(recipients, m.BCC...)
53		return recipients
54	}
55

